#requires -Version 5.1
param()
$ErrorActionPreference='Stop';Set-StrictMode -Off
$runtime=Join-Path (Split-Path $PSScriptRoot -Parent) 'wad'
. (Join-Path $runtime 'Pesto.Engine.Runtime.ps1')
$script:passed=0;$script:failed=0
function Assert($v,$why='Assertion failed'){if(-not$v){throw $why}}
function Case($name,[scriptblock]$body,[switch]$Reset){try{&$body;$script:passed++}catch{$script:failed++;Write-Host ('FAIL '+$name+': '+$_)}finally{if($Reset){Reset-PC}}}
function Reject([scriptblock]$body){$caught=$false;try{&$body|Out-Null}catch{$caught=$true};Assert $caught}
# Un refus n'est prouve que par le garde qui l'emet : la meme forme peut etre refusee par une garde
# en aval, ce qui laisserait passer une mutation de la garde amont. Le message est donc exige.
function RejectWith([scriptblock]$body,[string]$Needle){$caught='<aucun refus>';try{&$body|Out-Null}catch{$caught=[string]$_.Exception.Message};Assert ($caught.Contains($Needle)) ('refus attendu : '+$Needle+' ; obtenu : '+$caught)}
$nativeSource=(Get-Command Invoke-PestoOfflineNative).Definition
$temp=Join-Path $PSScriptRoot ('pesto-effects-'+[Guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($temp)
$script:DOMAINE='example.local';$script:DC='dc.example.local';$script:OU=@{ROOT='OU=Paris,DC=example,DC=local';SECOND='OU=Berlin,DC=example,DC=local';FOREIGN='OU=Berlin,DC=other,DC=local'};$script:OUV=@{};$script:CFG=[pscustomobject]@{};$script:SIM=$false;$script:GUI=$false
$script:PestoPolicy=[pscustomobject]@{Schema=1};$script:native=0;$script:adCalls=0;$script:writeFailure=$false;$script:nativeFailure=$false
$machine='11111111-1111-1111-1111-111111111111';$guid='22222222-2222-2222-2222-222222222222'
function Get-PestoAutomationMachineId {$machine}
function Get-PestoConfigurationSignature {param($Config);return ('a'*64)}
