function Get-PestoCampaignPolicy {return $script:campaignPolicy}
function Get-ADParams {return @{}}
$script:fixtureLedgerRoot=Join-Path $temp 'ledger';[void][IO.Directory]::CreateDirectory($script:fixtureLedgerRoot)
function Get-PestoInterventionRoot {return $script:fixtureLedgerRoot}
