function Get-ADComputer {param($Identity,$Properties,$ErrorAction);return $script:pc}
# Reference managedBy et ecriture AD : doubles de transport uniquement, aucune lecture ni ecriture reelle.
$script:refGuid='33333333-3333-3333-3333-333333333333';$script:refDn='CN=Admin Reference,OU=Paris,DC=example,DC=local'
$script:adObject=$null;$script:adObjectCalls=0;$script:swallowWrite=$false;$script:campaignPolicy=$null;$script:receiptWrites=0;$script:failWriteAt=0
function Get-ADObject {param($Identity,$Properties,$ErrorAction);$script:adObjectCalls++;return $script:adObject}
function New-Change($Attribute,$Before,$After,$ReferenceGuid=''){return [pscustomobject]@{Attribute=$Attribute;Before=$Before;After=$After;ReferenceGuid=$ReferenceGuid}}
function Resign-AttributePlan($Plan){$copy=[ordered]@{};foreach($property in $Plan.PSObject.Properties){if($property.Name -ne 'Integrity'){$copy[$property.Name]=$property.Value}};$Plan.Integrity=Get-PestoStableHash (ConvertTo-PestoCanonicalValue $copy);return $Plan}
function Copy-Receipt($OperationId,[scriptblock]$Edit){$path=Join-Path $script:fixtureLedgerRoot ($OperationId+'.json');$doc=Get-Content -LiteralPath $path -Raw -Encoding UTF8|ConvertFrom-Json;&$Edit $doc;$other=[Guid]::NewGuid().ToString('N');$doc.OperationId=$other;if($doc.Coordination){$doc.Coordination.Owner=$other};if($doc.PlanFingerprint){$doc.PlanFingerprint=Get-PestoPlanFingerprint $doc.Plan};[IO.File]::WriteAllText((Join-Path $script:fixtureLedgerRoot ($other+'.json')),($doc|ConvertTo-Json -Depth 12));return $other}
function Set-ADObject {param($Identity,$Replace,$Clear,$ErrorAction);$script:adCalls++;Assert ($script:ActiveIntervention.Attributes -eq 'Requested');if($script:nativeFailure){throw 'fixture interruption'};if($script:swallowWrite){return};foreach($k in $Replace.Keys){$script:pc.$k=$Replace[$k]};foreach($k in $Clear){$script:pc.$k=''}}
function Assert-PestoStoredMutationReady {param($Plan)}
function Write-PestoJoinReceipt {param($Path,$Receipt);$script:receiptWrites++;if($script:writeFailure -or ($script:failWriteAt -gt 0 -and $script:failWriteAt -eq $script:receiptWrites)){throw 'fixture disk failure'};Write-PestoAtomicText $Path ($Receipt|ConvertTo-Json -Depth 12)}
function Reset-PC {foreach($path in [IO.Directory]::GetFiles($script:fixtureLedgerRoot)){[IO.File]::Delete($path)};$script:pc=[pscustomobject]@{Name='P111301AA765001';ObjectGUID=$guid;DistinguishedName='CN=P111301AA765001,OU=Paris,DC=example,DC=local';description='old';location='old place';managedBy='';userAccountControl=4096};$script:adCalls=0;$script:nativeFailure=$false;$script:writeFailure=$false;$script:adObject=[pscustomobject]@{ObjectGUID=$script:refGuid;DistinguishedName=$script:refDn};$script:adObjectCalls=0;$script:swallowWrite=$false;$script:campaignPolicy=$null;$script:receiptWrites=0;$script:failWriteAt=0;$script:PestoPolicy=[pscustomobject]@{Schema=1}}
try{
 Reset-PC
 Case 'Preview has exact diff and makes no mutation' {$script:plan=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new';location=''});Assert ($script:plan.Changes.Count -eq 2);Assert ($script:plan.Changes[0].Before -eq 'old');Assert ($script:adCalls -eq 0)}
 Case 'Unknown AD attribute rejected' {RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{userAccountControl='0'})} -Needle 'Champ non autorisé'} -Reset
 Case 'Foreign managedBy refused before reference lookup' {Reject {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{managedBy='CN=X,DC=other,DC=local'})}}
 Case 'Stale before value refuses mutation' {$script:pc.description='someone else';$r=Invoke-PestoAttributeMutation $script:plan;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0);Reset-PC}
 Case 'Replaced GUID refuses mutation' {$script:pc.ObjectGUID=[Guid]::NewGuid();$r=Invoke-PestoAttributeMutation $script:plan;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0);Reset-PC}
 Case 'Persistence failure prevents AD write' {$script:writeFailure=$true;$r=Invoke-PestoAttributeMutation $script:plan;Assert ($script:adCalls -eq 0 -and $r.ExitCode -eq 96);Reset-PC}
 Case 'Replace and clear sent once, then observed' {$r=Invoke-PestoAttributeMutation $script:plan;Assert ($r.ExitCode -eq 0 -and $r.State -eq 'Verified') $r.Message;Assert ($script:adCalls -eq 1 -and $script:pc.description -eq 'new' -and $script:pc.location -eq '');Assert ((Read-PestoIntervention (Join-Path $script:fixtureLedgerRoot ($r.OperationId+'.json'))).Attributes -eq 'Confirmed');$script:attributeOp=$r.OperationId}
 Case 'Observation never repeats a Set-ADObject' {$r=Get-PestoAttributeObservation ([Guid]$script:attributeOp);Assert ($r.State -eq 'Verified' -and $script:adCalls -eq 1 -and -not $r.ReplayAllowed)}
 Case 'Divergent observation returns a nonzero code without mutation' {$script:pc.description='external';$r=Get-PestoAttributeObservation ([Guid]$script:attributeOp);Assert ($r.State -eq 'Uncertain' -and $r.ExitCode -eq 97 -and $script:adCalls -eq 1)}
 Case 'Native failure is uncertain, not retried' {Reset-PC;$script:nativeFailure=$true;$r=Invoke-PestoAttributeMutation $script:plan;Assert ($r.ExitCode -eq 97 -and $script:adCalls -eq 1 -and $r.MutationStarted);$again=Invoke-PestoAttributeMutation $script:plan;Assert ($again.ExitCode -eq 96 -and $script:adCalls -eq 1);Reset-PC}
 Case 'Tampered diff rejected even with unchanged plan checksum' {$p=$script:plan|ConvertTo-Json -Depth 10|ConvertFrom-Json;$p.Changes[0].After='altered';$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0)}
 # Gardes propres a l'extension attributs (point 114) : forme des valeurs, perimetre AD, dates du plan,
 # politique moteur, intention du recu. Les transports AD restent des doubles locaux, aucun appel reseau.
 Case 'Non-string attribute value refused' {RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description=12345})} -Needle 'Valeur attribut invalide.'} -Reset
 Case 'Oversized attribute value refused' {RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{location=('x'*1025)})} -Needle 'Valeur attribut invalide.'} -Reset
 Case 'Control character in attribute value refused' {RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description=('bad'+"`t"+'value')})} -Needle 'Valeur attribut invalide.'} -Reset
 Case 'managedBy without a distinguished name refused' {RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{managedBy='Administrator'})} -Needle 'managedBy exige un DN.'} -Reset
 Case 'No-op request produces no plan and no write' {Reset-PC;RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='old'})} -Needle 'Une a trois modifications requises.';Assert ($script:adCalls -eq 0)} -Reset
 Case 'Duplicate attribute refused by the diff guard' {$a=New-Change 'description' 'a' 'b';$b=New-Change 'description' 'c' 'd';RejectWith -body {Assert-PestoAttributeChanges @($a,$b)} -Needle 'Attribut inconnu ou duplique.'} -Reset
 Case 'Empty diff refused by the diff guard' {RejectWith -body {Assert-PestoAttributeChanges @(,(New-Change 'description' 'same' 'same'))} -Needle 'Diff vide.'} -Reset
 Case 'Control character in a diff side refused' {RejectWith -body {Assert-PestoAttributeChanges @(,(New-Change 'description' 'a' ('b'+"`n"+'f')))} -Needle 'Diff attribut invalide.'} -Reset
 Case 'Reference pinned only for managedBy' {RejectWith -body {Assert-PestoAttributeChanges @(,(New-Change 'location' 'a' 'b' '44444444-4444-4444-4444-444444444444'))} -Needle 'Reference inattendue.'} -Reset
 Case 'managedBy without reference identity refused' {RejectWith -body {Assert-PestoAttributeChanges @(,(New-Change 'managedBy' '' 'CN=Admin Reference,OU=Paris,DC=example,DC=local'))} -Needle 'Identite managedBy manquante.'} -Reset
 Case 'Fourth change refused by the diff guard' {$a=New-Change 'description' 'a' 'b';$b=New-Change 'location' 'c' 'd';$c=New-Change 'managedBy' '' 'CN=Admin Reference,OU=Paris,DC=example,DC=local' '55555555-5555-5555-5555-555555555555';$d=New-Change 'description' 'e' 'f';RejectWith -body {Assert-PestoAttributeChanges @($a,$b,$c,$d)} -Needle 'Une a trois modifications requises.'} -Reset
 Case 'Attribute outside the three allowed refused by the row guard' {RejectWith -body {Assert-PestoAttributeChanges @(,(New-Change 'userAccountControl' '4096' '0'))} -Needle 'Attribut inconnu ou duplique.'} -Reset
 Case 'Unknown field in a diff row refused' {RejectWith -body {Assert-PestoAttributeChanges @([pscustomobject]@{Attribute='description';Before='a';After='b';ReferenceGuid='';Extra='x'})} -Needle 'Champ non autorisé'} -Reset
 Case 'managedBy reference is pinned to its GUID' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{managedBy=$script:refDn});Assert ($p.Changes.Count -eq 1 -and $p.Changes[0].Attribute -ceq 'managedBy') 'managedBy diff missing';Assert ($p.Changes[0].ReferenceGuid -ceq $script:refGuid) 'reference GUID not pinned';Assert ($script:adObjectCalls -eq 1) 'reference resolved more than once'} -Reset
 Case 'Missing managedBy reference refuses the plan' {Reset-PC;$script:adObject=$null;RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{managedBy=$script:refDn})} -Needle 'Reference managedBy absente.';Reset-PC} -Reset
 Case 'Reference moved between plan and execution refuses the write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{managedBy=$script:refDn});$script:adObject=[pscustomobject]@{ObjectGUID=$script:refGuid;DistinguishedName='CN=Moved Reference,OU=Paris,DC=example,DC=local'};$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'moved reference still wrote AD'} -Reset
 Case 'Target outside the configured OU scope refused' {Reset-PC;$script:pc.DistinguishedName='CN=P111301AA765001,OU=Nowhere,DC=example,DC=local';RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'})} -Needle 'Identite ou perimetre AD non confirme.';Assert ($script:adCalls -eq 0);Reset-PC} -Reset
 Case 'Target in a configured OU of another domain refused' {Reset-PC;$script:pc.DistinguishedName='CN=P111301AA765001,OU=Berlin,DC=other,DC=local';RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'})} -Needle 'Identite ou perimetre AD non confirme.';Reset-PC} -Reset
 Case 'Target GUID returned by AD does not match the request' {Reset-PC;$script:pc.ObjectGUID=[Guid]::NewGuid().ToString('D');RejectWith -body {New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'})} -Needle 'Identite ou perimetre AD non confirme.';Reset-PC} -Reset
 Case 'Empty target GUID refused' {RejectWith -body {Get-PestoAttributeTarget ([Guid]::Empty)} -Needle 'GUID cible requis.'} -Reset
 Case 'Target moved after preparation refuses the write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$script:pc.DistinguishedName='CN=P111301AA765001,OU=Berlin,DC=example,DC=local';$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'moved target still wrote AD';Reset-PC} -Reset
 Case 'Target renamed after preparation refuses the write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$script:pc.Name='P111301AA765002';$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'renamed target still wrote AD';Reset-PC} -Reset
 Case 'Expired plan refuses the write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$p.CreatedUtc=[DateTimeOffset]::UtcNow.AddHours(-2).ToString('o');$p.ExpiresUtc=[DateTimeOffset]::UtcNow.AddMinutes(-5).ToString('o');[void](Resign-AttributePlan $p);$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'expired plan still wrote AD';Reset-PC} -Reset
 Case 'Plan from another configuration signature refuses the write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$p.ConfigStamp=('b'*64);[void](Resign-AttributePlan $p);$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'foreign configuration still wrote AD';Reset-PC} -Reset
 Case 'Plan prepared on another machine refuses the write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$p.MachineId='99999999-9999-9999-9999-999999999999';[void](Resign-AttributePlan $p);$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'foreign machine still wrote AD';Reset-PC} -Reset
 Case 'Plan for another domain refuses the write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$p.Domain='other.local';[void](Resign-AttributePlan $p);$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'foreign domain still wrote AD';Reset-PC} -Reset
 Case 'Effect persistence failure blocks the AD write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='unpersisted effect'});$script:failWriteAt=2;$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and -not $r.MutationStarted -and $script:adCalls -eq 0) 'AD written before the effect was persisted';Reset-PC} -Reset
 Case 'Write not visible on read-back stays uncertain and is never replayed' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='pending replication'});$script:swallowWrite=$true;$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 97 -and $r.MutationStarted -and $script:adCalls -eq 1) 'silent write not reported uncertain';$again=Invoke-PestoAttributeMutation $p;Assert ($again.ExitCode -eq 96 -and $script:adCalls -eq 1) 'unconfirmed write was replayed';Reset-PC} -Reset
 Case 'Incident mode suspends the attribute write before AD' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$script:PestoPolicy=[pscustomobject]@{Schema=1;IncidentMode=$true};$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'incident mode still wrote AD';Reset-PC} -Reset
 Case 'Excluded computer name refuses the attribute write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$script:PestoPolicy=[pscustomobject]@{Schema=1;ExcludedNames=@('P111301AA765001')};$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'excluded name still wrote AD';Reset-PC} -Reset
 Case 'Excluded OU refuses the attribute write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$script:PestoPolicy=[pscustomobject]@{Schema=1;ExcludedOUs=@('OU=Paris,DC=example,DC=local')};$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'excluded OU still wrote AD';Reset-PC} -Reset
 Case 'Domain controller target refuses the attribute write' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'});$script:pc.userAccountControl=8192;$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'domain controller still wrote AD';Reset-PC} -Reset
 Case 'Campaign-tagged attribute plan requires an approval' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='new'}) ([pscustomobject]@{Campaign='campagne-a'});$script:campaignPolicy=[pscustomobject]@{Campaigns=@('campagne-a');Signers=@()};$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 96 -and $script:adCalls -eq 0) 'campaign mutation ran without approval';Reset-PC} -Reset
 Case 'Read-only observation never confirms the receipt' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='observed value'});$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 0) 'preparation for the read-only observation failed';$path=Join-Path $script:fixtureLedgerRoot ($r.OperationId+'.json');$before=[IO.File]::ReadAllText($path);$env:PESTO_READONLY_SESSION='1';try{$o=Get-PestoAttributeObservation ([Guid]$r.OperationId)}finally{$env:PESTO_READONLY_SESSION=$null};Assert ($o.State -ceq 'Verified' -and $o.ExitCode -eq 0) 'read-only observation did not verify';Assert ([IO.File]::ReadAllText($path) -ceq $before) 'read-only observation rewrote the receipt';[void](Get-PestoAttributeObservation ([Guid]$r.OperationId));Assert ([IO.File]::ReadAllText($path) -cne $before) 'writable observation recorded nothing';Reset-PC} -Reset
 Case 'Observation refuses a receipt from another domain' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='foreign receipt'});$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 0) 'receipt for the domain test not produced';$other=Copy-Receipt $r.OperationId {$args[0].Plan.Domain='other.local'};RejectWith -body {Get-PestoAttributeObservation ([Guid]$other)} -Needle 'Recu attributs incompatible.';Reset-PC} -Reset
 Case 'Observation refuses a receipt without an attribute intention' {Reset-PC;$p=New-PestoAttributePlan ([Guid]$guid) ([pscustomobject]@{description='untracked effect'});$r=Invoke-PestoAttributeMutation $p;Assert ($r.ExitCode -eq 0) 'receipt for the intention test not produced';$other=Copy-Receipt $r.OperationId {$args[0].Attributes='NotRequested'};RejectWith -body {Get-PestoAttributeObservation ([Guid]$other)} -Needle 'Recu attributs incompatible.';Reset-PC} -Reset
 # DPAPI and djoin are transport doubles only; no native Windows call or AD connection.
 function Protect-PestoOfflineBytes {param([byte[]]$Bytes);return ,([byte[]]@($Bytes|ForEach-Object{$_ -bxor 42}))}
 function Unprotect-PestoOfflineBytes {param([byte[]]$Bytes);return ,([byte[]]@($Bytes|ForEach-Object{$_ -bxor 42}))}
 $script:local=[pscustomobject]@{Computer='P111301AA765001';PartOfDomain=$false;PendingRename=$false;Admin=$true;DomainRole=0;MachineId=$machine;BootUtc='2026-10-17T10:00:00Z';Domain='WORKGROUP'}
 function Get-PestoJoinLocalStatus {return $script:local}
 function Invoke-PestoOfflineNative {param($Path);$script:native++;$id=[IO.Path]::GetFileName($Path).Replace('.odj.tmp','');$r=Read-PestoOfflineRecord $id;Assert ($r.State -eq 'Requested') 'Intent must precede native call';Assert ([IO.File]::ReadAllText($Path) -like 'fixture-*');if($script:nativeFailure){throw 'fixture native interruption'};return 0}
 function Import-PestoADModule {param($ADModulePath)}
 function Get-DomainController {param($Domain);return 'dc.example.local'}
 function Test-ComputerSecureChannel {param($Server,$ErrorAction);return $script:secure}
 $source=Join-Path $temp 'source.blob';[IO.File]::WriteAllText($source,'fixture-secret-one')
 Case 'Import protects secret and exports only its hash' {$script:import=Import-PestoOfflineBlob $source ([Guid]$guid) $script:OU.ROOT;Assert ($script:import.State -eq 'Imported');$paths=Get-PestoOfflinePaths $script:import.BlobId;Assert (-not [IO.File]::ReadAllText($paths.State).Contains('fixture-secret'));Assert (-not [IO.File]::ReadAllText($paths.Secret).Contains('fixture-secret'));Assert ([IO.File]::Exists($source))}
 Case 'Same blob cannot be reimported' {Reject {Import-PestoOfflineBlob $source ([Guid]$guid) $script:OU.ROOT}}
 Case 'Wrong current machine name prevents ODJ' {$script:local.Computer='OTHER';Reject {Invoke-PestoOfflineApply $script:import.BlobId};Assert ($script:native -eq 0);$script:local.Computer='P111301AA765001'}
 Case 'Durable intent precedes single native application' {$r=Invoke-PestoOfflineApply $script:import.BlobId;Assert ($r.ExitCode -eq 3010 -and $r.State -eq 'PendingRestart' -and $script:native -eq 1);$paths=Get-PestoOfflinePaths $script:import.BlobId;Assert (-not [IO.File]::Exists($paths.Plain) -and -not [IO.File]::Exists($paths.Secret))}
 Case 'Repeated request does not call djoin' {$r=Invoke-PestoOfflineApply $script:import.BlobId;Assert ($r.ExitCode -eq 97 -and $script:native -eq 1)}
 Case 'No reboot is not a successful observation' {$r=Get-PestoOfflineObservation $script:import.BlobId $runtime $null;Assert ($r.State -eq 'Uncertain')}
 $script:local.PartOfDomain=$true;$script:local.Domain=$script:DOMAINE;$script:local.BootUtc='2026-10-18T10:00:00Z';$script:secure=$false
 Case 'Broken secure channel remains uncertain' {$r=Get-PestoOfflineObservation $script:import.BlobId $runtime $null;Assert ($r.State -eq 'Uncertain' -and -not $r.SecureChannel)}
 $script:secure=$true
 Case 'GUID, reboot, domain and channel reconcile existing receipt' {$r=Get-PestoOfflineObservation $script:import.BlobId $runtime $null;Assert ($r.State -eq 'Verified' -and $script:native -eq 1);Assert ((Read-PestoOfflineRecord $script:import.BlobId).State -eq 'Verified');$saved=Read-PestoIntervention (Join-Path $script:fixtureLedgerRoot ($r.OperationId+'.json'));Assert ($saved.OfflineJoin -eq 'Verified' -and $saved.Phase -eq 'Verified')}
 $script:local.PartOfDomain=$false;$script:nativeFailure=$true;[IO.File]::WriteAllText($source,'fixture-secret-two')
 Case 'Interrupted application has persistent no-replay state and no plaintext' {$i=Import-PestoOfflineBlob $source ([Guid]$guid) $script:OU.ROOT;Reject {Invoke-PestoOfflineApply $i.BlobId};Assert ((Read-PestoOfflineRecord $i.BlobId).State -eq 'Uncertain');$n=$script:native;[void](Invoke-PestoOfflineApply $i.BlobId);Assert ($script:native -eq $n);Assert (-not [IO.File]::Exists((Get-PestoOfflinePaths $i.BlobId).Plain))}
 Case 'ODJ effect is isolated from online join' {$fn=(Get-Command Invoke-PestoOfflineApply).Definition;Assert (-not $fn.Contains('Add-Computer') -and -not $fn.Contains('AddToDomain'));Assert ($nativeSource.Contains('/requestodj'))}
}finally{[IO.Directory]::Delete($temp,$true)}
Write-Host "ExtensionEffects: $script:passed passed, $script:failed failed. Real receipt lifecycle and schema; AD/DPAPI/djoin/ACL transports mocked; no VM."
